package com.bank.uuidchoice.service;

import com.bank.uuidchoice.model.LedgerEntry;
import com.bank.uuidchoice.model.PaymentRequest;
import com.bank.uuidchoice.repository.LedgerEntryRepository;
import com.bank.uuidchoice.repository.PaymentRequestRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
public class PaymentRequestService {
    private static final Logger log = LoggerFactory.getLogger(PaymentRequestService.class);
    private final PaymentRequestRepository requestRepo;
    private final LedgerEntryRepository ledgerRepo;

    public PaymentRequestService(PaymentRequestRepository requestRepo,
                                 LedgerEntryRepository ledgerRepo) {
        this.requestRepo = requestRepo;
        this.ledgerRepo = ledgerRepo;
    }

    // request_id is a UUID supplied by the device (minted offline, unguessable)
    @Transactional
    public LedgerEntry accept(UUID deviceMintedId, String accountId, BigDecimal amount) {
        PaymentRequest req = new PaymentRequest(deviceMintedId, accountId, amount);
        requestRepo.save(req);
        log.info("Accepted payment request {} (UUID: offline-minted, unguessable)", deviceMintedId);

        // Ledger uses a compact auto-increment id (central, write-heavy, time-queried)
        LedgerEntry entry = new LedgerEntry(deviceMintedId, amount);
        LedgerEntry saved = ledgerRepo.save(entry);
        log.info("Posted ledger entry {} (BIGINT sequence: compact, time-ordered)",
                 saved.getEntryId());
        return saved;
    }
}
